cd /tmp/<path>; cat > /tmp/sim.py <<'E'
import sys
P=[l.split(';')[0].split() for l in open(sys.argv[1])]
P=[p for p in P if p]
r=dict(a=0,b=0,c=0,d=0)
v=lambda x:r[x] if x in r else int(x)
pc=0;n=0;s=0;skip=False
while 0<=pc<len(P):
    p=P[pc];op=p[0]
    if skip: skip=False;pc+=1;continue
    n+=1;nx=pc+1
    if op=='set':r[p[1]]=v(p[2])%65536
    elif op=='add':r[p[1]]=(r[p[1]]+v(p[2]))%65536
    elif op=='mul':r[p[1]]=(r[p[1]]*v(p[2]))%65536
    elif op=='mod':
        if v(p[2])>0:r[p[1]]%=v(p[2])
    elif op=='dec':r[p[1]]=max(0,r[p[1]]-1)
    elif op=='jnz':
        if v(p[1])!=0:nx=pc+v(p[2])
    elif op=='skp':
        if v(p[1])<v(p[2]):skip=True
    elif op=='out':s+=v(p[1])
    pc=nx
print(s,n)
E
python3 -I /tmp/sim.py prog.pw9 | tee answer.txt
